    cleaned = []
    seen_date = False
    for ln in lines:
        if any(p in ln for p in SKIP_PHRASES):
            continue
        if re.search(r"\bTranslations?\b$", ln):
            continue
        if re.search(r"\bTranslation\b", ln) and ln.strip().endswith("Translation"):
            continue
        if ln == "":
            cleaned.append("")
            continue
        if DATE_RE.match(ln):
            seen_date = True
        # Drop stray header line between title and date
        if not seen_date and ln == "Y Combinator.":
            continue
        cleaned.append(ln)
        if ln == title or DATE_RE.match(ln):
            cleaned.append("")

    # Collapse multiple blank lines
    collapsed = []
    for ln in cleaned:
        if ln == "":
            if collapsed and collapsed[-1] != "":
                collapsed.append("")
        else:
            collapsed.append(ln)

    # Trim leading/trailing blanks
    while collapsed and collapsed[0] == "":
        collapsed.pop(0)
    while collapsed and collapsed[-1] == "":
        collapsed.pop()

    return collapsed


def lines_to_paragraphs(lines):
    paras = []
    cur = []
    for ln in lines:
        if ln == "":
            if cur:
                paras.append(" ".join(cur))
                cur = []
        else:
            cur.append(ln)
    if cur:
        paras.append(" ".join(cur))
    return paras


def split_long_paragraph(p: str):
    if len(p) <= MAX_CHARS:
        return [p]
    sentences = re.split(r"(?<=[.!?])\s+", p)
    parts = []
    cur = ""
    for s in sentences:
        if not s:
            continue
        if len(cur) + (1 if cur else 0) + len(s) <= MAX_CHARS:
            cur = s if not cur else cur + " " + s
        else:
            if cur:
                parts.append(cur)
            if len(s) > MAX_CHARS:
                for i in range(0, len(s), MAX_CHARS):
                    parts.append(s[i:i+MAX_CHARS])
                cur = ""
            else:
                cur = s
    if cur:
        parts.append(cur)
    return parts


all_paragraphs = []
for essay in ESSAYS:
    lines = extract_lines(essay["url"], essay["title"])
    if not lines:
        raise RuntimeError(f"No text extracted for {essay['title']}")
    paragraphs = lines_to_paragraphs(lines)
    all_paragraphs.extend(paragraphs)
    all_paragraphs.append("")  # paragraph break between essays

# Remove trailing empty paragraph
if all_paragraphs and all_paragraphs[-1] == "":
    all_paragraphs.pop()

# Expand any long paragraphs
expanded_paragraphs = []
for p in all_paragraphs:
    if p == "":
        expanded_paragraphs.append("")
    else:
        expanded_paragraphs.extend(split_long_paragraph(p))

# Chunk paragraphs
chunks = []
current = ""
for p in expanded_paragraphs:
    if p == "":
        if current:
            current = current + "\n\n"
        continue
    if not current:
        current = p
        continue
    if len(current) + 2 + len(p) <= MAX_CHARS:
        current = current + "\n\n" + p
    else:
        chunks.append(current.strip())
        current = p
if current:
